input.command:
cd /tmp && echo "=== sbir news/main ===" && curl -sk --max-time 30 -w "
HTTP=%{http_code}
" https://sbir.org.tw/news/main -o sbir_news.html && wc -c sbir_news.html; echo "=== sbir cross/notice ===" && curl -sk --max-time 30 -w "
HTTP=%{http_code}
" https://sbir.org.tw/cross/notice -o sbir_cross.html && wc -c sbir_cross.html

cd /tmp && curl -sk --max-time 60 -o sat.pdf "https://eii.nat.gov.tw/tiip/FilesSummernote/News/files/%E8%87%AA%E9%81%A9%E6%87%89%E8%A1%9B%E6%98%9F%E9%80%9A%E8%A8%8A%E9%85%AC%E8%BC%89%E8%88%87%E5%A4%9A%E8%BB%8C%E8%A1%9B%E6%98%9F%E5%9C%B0%E9%9D%A2%E7%B5%82%E7%AB%AF%E9%96%8B%E7%99%BC%E8%A3%9C%E5%8A%A9%E8%A8%88%E7%95%AB-%E5%85%AC%E5%91%8A(%E5%90%AB%E5%85%AC%E5%91%8A%E4%BA%8B%E9%A0%85)(2).pdf" -w "HTTP=%{http_code} bytes=%{size_download}\n" && (python3 -c "
try:
    import pypdf; r=pypdf.PdfReader('sat.pdf'); print('\n'.join(p.extract_text() for p in r.pages))
except Exception as e: print('ERR',e)
" 2>&1 | head -120)

cd /tmp && curl -sk --max-time 60 -o sat_apply.pdf "https://eii.nat.gov.tw/tiip/FilesSummernote/News/files/%E8%87%AA%E9%81%A9%E6%87%89%E8%A1%9B%E6%98%9F%E9%80%9A%E8%A8%8A%E9%85%AC%E8%BC%89%E8%88%87%E5%A4%9A%E8%BB%8C%E8%A1%9B%E6%98%9F%E5%9C%B0%E9%9D%A2%E7%B5%82%E7%AB%AF%E9%96%8B%E7%99%BC%E8%A3%9C%E5%8A%A9%E8%A8%88%E7%95%AB-%E7%94%B3%E8%AB%8B%E9%A0%88%E7%9F%A5(1).pdf" -w "HTTP=%{http_code} bytes=%{size_download}\n" && python3 -c "
import pypdf,re; r=pypdf.PdfReader('sat_apply.pdf'); t='\n'.join(p.extract_text() for p in r.pages)
t2=re.sub(r'\s+','',t)
for kw in ['補助款上限','補助上限','補助金額','萬元','億元','補助比例']:
    for m in re.finditer(kw,t2):
        print(kw,'>>>',t2[max(0,m.start()-120):m.start()+120]); print('---')
" 2>&1 | head -60
